{
  "findings": [
    {
      "ref": "[D517]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child, and it is on by default.",
      "stance": "risk",
      "quote": "With big buttons for little fingers and easy navigation, browsing and watching videos is a snap."
    },
    {
      "ref": "[D517]",
      "area": "money",
      "claim": "A parent reports that the app pushes in-app purchases or loot boxes.",
      "stance": "risk",
      "quote": "Based on 41 parent reviews\n* repetitive content\n* inappropriate videos\n* lack of educational value\n* poor parental controls"
    },
    {
      "ref": "[D517]",
      "area": "data",
      "claim": "A parent reports that the app collects data for ads or shares it with third parties, and the data can be deleted.",
      "stance": "neutral",
      "quote": "In the \"grown-ups only\" Settings menu, parents can toggle sounds on and off, disable search (which limits viewable videos to only those on the home screen), and clear the watch history."
    },
    {
      "ref": "[D517]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice, going by what parents report.",
      "stance": "mitigation",
      "quote": "The settings section has a parent gate for which users need to complete a simple multiplication problem."
    },
    {
      "ref": "[D517]",
      "area": "content",
      "claim": "A parent reports that the app contains inappropriate videos such as those with wine and beer.",
      "stance": "risk",
      "quote": "Curated videos updated periodically. Presence of potentially inappropriate content may fluctuate; parents have reported videos containing wine and beer."
    },
    {
      "ref": "[D517]",
      "area": "developer_record",
      "claim": "A parent reports that the developer has had fines, breaches, lawsuits or regulatory actions.",
      "stance": "neutral",
      "quote": "Research shows a connection between kids' healthy self-esteem and positive portrayals in media."
    }
  ]
}
